const QB = {"de": [{"q": "Ngày Chuyển đổi số quốc gia là ngày nào trong năm?", "a": "Ngày 10/10", "w": ["Ngày 1/10", "Ngày 20/11", "Ngày 2/9"], "h": "Ngày và tháng giống hệt nhau, gợi nhớ hai chữ số 1 và 0 của máy tính.", "e": "Quyết định số 505/QĐ-TTg ngày 22/4/2022 của Thủ tướng Chính phủ lấy ngày 10/10 hằng năm là Ngày Chuyển đổi số quốc gia; con số 10 gợi nhớ hai chữ số 1 và 0 của máy tính. Ngày 1/10 là Ngày Quốc tế Người cao tuổi, 20/11 là Ngày Nhà giáo Việt Nam, 2/9 là Ngày Quốc khánh."}, {"q": "VNeID là gì?", "a": "Ứng dụng định danh và xác thực điện tử do Bộ Công an phát triển", "w": ["Ứng dụng mạng xã hội để kết bạn, nhắn tin", "Ví điện tử của một ngân hàng", "Ứng dụng gọi xe công nghệ"], "h": "“ID” là viết tắt tiếng Anh của từ “danh tính”.", "e": "VNeID là ứng dụng định danh điện tử của Bộ Công an, giúp người dân dùng giấy tờ điện tử thay giấy tờ giấy, đăng nhập dịch vụ công, tra cứu thông tin cư trú. VNeID không phải mạng xã hội, ví điện tử hay ứng dụng gọi xe."}, {"q": "Khi thanh toán bằng cách quét mã QR, cần làm gì trước khi bấm xác nhận chuyển tiền?", "a": "Kiểm tra tên người nhận và số tiền hiển thị trên ứng dụng", "w": ["Chụp màn hình gửi cho người thân", "Tắt mạng điện thoại", "Đọc to số tài khoản cho người bán nghe"], "h": "Hãy nhìn kỹ màn hình trước khi bấm nút cuối cùng.", "e": "Kẻ gian có thể dán đè mã QR giả lên mã thật. Kiểm tra tên người nhận và số tiền giúp tránh chuyển nhầm hoặc chuyển cho kẻ gian. Các việc còn lại không giúp kiểm tra giao dịch."}, {"q": "Bạn nhận tin nhắn: “Chúc mừng bạn trúng xe máy, bấm vào đường link để nhận thưởng”. Bạn nên làm gì?", "a": "Không bấm link, xóa tin nhắn và cảnh báo người thân", "w": ["Bấm vào link ngay để nhận thưởng", "Gửi ảnh thẻ căn cước để làm thủ tục nhận thưởng", "Chuyển khoản “phí nhận thưởng” theo yêu cầu"], "h": "Quà to từ người lạ thường là cái bẫy.", "e": "Đây là chiêu lừa đảo phổ biến: đường link lạ có thể cài mã độc, đánh cắp tài khoản; yêu cầu gửi giấy tờ hoặc nộp phí để nhận thưởng đều là dấu hiệu lừa đảo."}, {"q": "Một người tự xưng là nhân viên ngân hàng gọi điện xin mã OTP vừa gửi về máy bạn. Bạn nên làm gì?", "a": "Không cung cấp, cúp máy và gọi lại tổng đài chính thức của ngân hàng", "w": ["Đọc mã vì họ biết đúng họ tên của mình", "Đọc mã nếu họ nói chuyện lịch sự", "Gửi mã qua Zalo cho họ"], "h": "Mã OTP là chìa khóa riêng, ngân hàng không bao giờ xin.", "e": "Ngân hàng không bao giờ yêu cầu khách hàng cung cấp mã OTP. Ai có mã OTP có thể thực hiện giao dịch trên tài khoản của bạn. Kẻ gian thường biết trước họ tên, số điện thoại, nên đừng vì thế mà tin."}, {"q": "Dịch vụ công trực tuyến mang lại lợi ích gì cho người dân?", "a": "Nộp hồ sơ thủ tục hành chính qua mạng, giảm đi lại, tiết kiệm thời gian", "w": ["Mua hàng giảm giá trên mạng", "Xem phim miễn phí", "Nhận tiền thưởng mỗi lần đăng nhập"], "h": "Chữ “công” trong tên gọi liên quan đến cơ quan nhà nước.", "e": "Dịch vụ công trực tuyến là dịch vụ hành chính công được cơ quan nhà nước cung cấp qua mạng, giúp người dân nộp hồ sơ, theo dõi tiến độ và nhận kết quả mà không phải đến nhiều lần. Các đáp án còn lại không phải dịch vụ công."}, {"q": "Khi dùng wifi miễn phí ở quán cà phê, bạn KHÔNG nên làm việc nào sau đây?", "a": "Đăng nhập ứng dụng ngân hàng để chuyển tiền", "w": ["Đọc báo điện tử", "Xem bản đồ chỉ đường", "Nghe nhạc"], "h": "Hãy nghĩ đến việc liên quan đến tiền bạc.", "e": "Wifi công cộng có thể bị kẻ gian theo dõi, đánh cắp dữ liệu. Khi giao dịch ngân hàng nên dùng mạng di động 4G/5G. Đọc báo, xem bản đồ, nghe nhạc ít rủi ro hơn."}, {"q": "Mật khẩu nào sau đây an toàn nhất?", "a": "Gd@Phuong#2026xanh", "w": ["123456", "01011990 (ngày sinh)", "matkhau"], "h": "Mật khẩu mạnh thường dài và “lộn xộn” nhất.", "e": "Mật khẩu mạnh nên dài, kết hợp chữ hoa, chữ thường, chữ số và ký tự đặc biệt. 123456, ngày sinh hay chữ “matkhau” là những mật khẩu dễ bị đoán nhất."}, {"q": "Con chip trên thẻ căn cước dùng để làm gì?", "a": "Lưu trữ thông tin của công dân để xác thực nhanh, chính xác", "w": ["Định vị nơi người mang thẻ đang đứng", "Thanh toán như thẻ ATM", "Nghe lén cuộc gọi điện thoại"], "h": "Chip giống như một cuốn sổ nhỏ, không phải chiếc máy định vị.", "e": "Chip lưu thông tin nhân thân và sinh trắc học, giúp xác thực nhanh khi làm thủ tục. Chip không có chức năng định vị hay nghe lén, đó là tin đồn sai sự thật; thẻ căn cước cũng không phải thẻ thanh toán."}, {"q": "Hiểu đơn giản, chuyển đổi số là gì?", "a": "Ứng dụng công nghệ số để thay đổi cách sống, làm việc, quản lý cho hiệu quả hơn", "w": ["Chỉ cần scan giấy tờ thành file là xong", "Mua thật nhiều máy tính mới", "Việc riêng của các công ty công nghệ"], "h": "Chuyển đổi số là việc của mọi người, không chỉ là mua máy móc.", "e": "Chuyển đổi số là thay đổi cách làm nhờ công nghệ số và dữ liệu, lấy người dân làm trung tâm. Scan giấy tờ hay mua máy chỉ là một phần nhỏ; chuyển đổi số là việc của toàn dân, không riêng doanh nghiệp công nghệ."}, {"q": "Ứng dụng nào cho phép bạn tra cứu thông tin cư trú của bản thân?", "a": "VNeID", "w": ["YouTube", "TikTok", "Google Maps"], "h": "Ứng dụng này do Bộ Công an phát triển.", "e": "VNeID cho phép xem thông tin cư trú, thông tin thẻ căn cước và nhiều giấy tờ đã tích hợp. Các ứng dụng còn lại dùng để xem video, mạng xã hội hoặc bản đồ."}, {"q": "Trước khi chia sẻ một tin “nóng” trên mạng xã hội, bạn nên làm gì?", "a": "Kiểm tra lại từ nguồn chính thống như báo chí, trang của cơ quan nhà nước", "w": ["Chia sẻ ngay nếu có nhiều lượt thích", "Chia sẻ nếu tiêu đề gây sốc", "Cứ chia sẻ trước, sai thì xóa sau"], "h": "Nhiều người thích chưa chắc đã đúng.", "e": "Tin giả lan rất nhanh, gây hoang mang; người chia sẻ thông tin sai sự thật có thể bị xử lý theo quy định. Lượt thích hay tiêu đề giật gân không chứng minh tin là thật."}, {"q": "Ở khu phố, ai có nhiệm vụ hướng dẫn người dân cài VNeID, sử dụng dịch vụ công trực tuyến?", "a": "Tổ công nghệ số cộng đồng", "w": ["Tổ hòa giải", "Ban quản lý chợ", "Câu lạc bộ dưỡng sinh"], "h": "Chính là chúng tôi đây!", "e": "Tổ công nghệ số cộng đồng ở khu phố có nhiệm vụ đến từng nhà hướng dẫn người dân sử dụng nền tảng số, dịch vụ công trực tuyến và kỹ năng số. Các tổ chức còn lại có nhiệm vụ khác."}, {"q": "Khi bị mất điện thoại có cài ứng dụng ngân hàng, việc nên làm ngay là gì?", "a": "Báo nhà mạng khóa SIM và báo ngân hàng tạm khóa tài khoản", "w": ["Chờ người nhặt được gọi lại", "Đăng lên mạng xã hội nhờ tìm giúp", "Mua điện thoại mới rồi tính sau"], "h": "Hãy nghĩ đến nơi giữ tiền và nơi nhận mã OTP của bạn.", "e": "Khóa SIM giúp kẻ gian không nhận được mã OTP; tạm khóa tài khoản để bảo vệ tiền. Chờ đợi hoặc chỉ đăng lên mạng có thể khiến bạn bị mất tiền."}, {"q": "“AI” là viết tắt tiếng Anh của cụm từ nào?", "a": "Trí tuệ nhân tạo", "w": ["Mạng Internet tốc độ cao", "Phần mềm diệt virus", "Ứng dụng tự động cập nhật"], "h": "Công nghệ này giúp máy móc “suy nghĩ” và trả lời như con người.", "e": "AI là trí tuệ nhân tạo, công nghệ giúp máy tính học hỏi, hiểu ngôn ngữ, nhận dạng hình ảnh. Các đáp án còn lại là những khái niệm khác."}], "tb": [{"q": "“Dịch vụ công trực tuyến toàn trình” nghĩa là gì?", "a": "Mọi bước từ nộp hồ sơ, xử lý đến nhận kết quả đều thực hiện trên môi trường mạng", "w": ["Nộp hồ sơ trên mạng, khi nhận kết quả mang bản giấy đến đối chiếu", "Điền tờ khai trên mạng, in ra rồi nộp tại Trung tâm Phục vụ hành chính công", "Nộp hồ sơ được tại bất kỳ xã, phường nào trên cả nước"], "h": "“Toàn trình” là không có bước nào phải đến trực tiếp.", "e": "Toàn trình là thực hiện trọn vẹn trên mạng. Hai cách “nộp mạng rồi mang giấy đến” hay “điền mạng rồi nộp giấy” chỉ là dịch vụ công trực tuyến một phần. Nộp ở bất kỳ xã, phường nào là “không phụ thuộc địa giới hành chính”, một khái niệm khác."}, {"q": "Trang web của cơ quan nhà nước Việt Nam có đuôi tên miền nào?", "a": ".gov.vn", "w": [".vn", ".org.vn", ".com.vn"], "h": "“gov” là viết tắt của từ “chính phủ” trong tiếng Anh.", "e": "Tên miền .gov.vn dành riêng cho cơ quan nhà nước, ví dụ dichvucong.gov.vn. Đuôi .vn là tên miền quốc gia mà tổ chức, cá nhân nào cũng đăng ký được; .org.vn thường dùng cho các tổ chức, hội; .com.vn dùng cho thương mại. Trang tự xưng cơ quan nhà nước mà không có đuôi .gov.vn thì cần cảnh giác."}, {"q": "Theo quy định hiện hành, tài khoản định danh điện tử của công dân Việt Nam được chia thành mấy mức độ?", "a": "2 mức độ (mức độ 1 và mức độ 2)", "w": ["3 mức độ (mức độ 1, 2 và 3)", "4 mức độ (từ mức độ 1 đến mức độ 4)", "1 mức độ chung cho mọi công dân"], "h": "Chỉ có “mức 1” và một mức cao hơn nó.", "e": "Theo Nghị định 69/2024/NĐ-CP (đã được sửa đổi, bổ sung năm 2026), tài khoản định danh điện tử của công dân gồm mức độ 1 và mức độ 2; mức độ 2 có thêm thông tin vân tay nên độ tin cậy cao hơn. Cách chia 4 mức là cách phân loại dịch vụ công trực tuyến trước đây, không phải tài khoản định danh."}, {"q": "Đề án 06 của Chính phủ có tên đầy đủ là gì?", "a": "Phát triển ứng dụng dữ liệu về dân cư, định danh và xác thực điện tử phục vụ chuyển đổi số quốc gia", "w": ["Phát triển Chính phủ điện tử hướng tới Chính phủ số", "Xây dựng và vận hành Cổng Dịch vụ công quốc gia", "Phổ cập kiến thức, kỹ năng số cho toàn dân"], "h": "Đề án do Bộ Công an chủ trì, gắn với VNeID và thẻ căn cước.", "e": "Đề án 06 được phê duyệt tại Quyết định số 06/QĐ-TTg ngày 06/01/2022 của Thủ tướng Chính phủ, giai đoạn 2022 – 2025, tầm nhìn đến 2030. Chính phủ số, Cổng Dịch vụ công quốc gia và phổ cập kỹ năng số đều liên quan đến chuyển đổi số nhưng là những nhiệm vụ, chương trình khác."}, {"q": "Sổ hộ khẩu giấy chính thức hết giá trị sử dụng từ ngày nào?", "a": "01/01/2023", "w": ["01/7/2021", "01/7/2024", "01/01/2025"], "h": "Sổ còn được dùng thêm khoảng một năm rưỡi sau khi Luật Cư trú 2020 có hiệu lực.", "e": "Theo khoản 3 Điều 38 Luật Cư trú 2020, sổ hộ khẩu, sổ tạm trú được dùng đến hết ngày 31/12/2022, nên hết giá trị từ 01/01/2023. Ngày 01/7/2021 là ngày Luật Cư trú có hiệu lực (ngừng cấp mới sổ); 01/7/2024 là ngày Luật Căn cước có hiệu lực; 01/01/2025 là mốc chứng minh nhân dân hết giá trị."}, {"q": "Theo Luật Căn cước 2023 (hiệu lực từ 01/7/2024), thẻ Căn cước công dân được đổi tên thành gì?", "a": "Thẻ căn cước", "w": ["Thẻ căn cước điện tử", "Thẻ định danh công dân", "Thẻ căn cước công dân gắn chip"], "h": "Tên mới chỉ còn hai chữ.", "e": "Luật Căn cước 2023 đổi tên thành “thẻ căn cước”; thẻ Căn cước công dân cấp trước đó vẫn dùng đến hết hạn in trên thẻ. “Căn cước điện tử” là loại khác: mỗi công dân được cấp 01 căn cước điện tử, không phải tên của thẻ. “Thẻ căn cước công dân gắn chip” là tên gọi cũ; “thẻ định danh công dân” không có trong luật."}, {"q": "“Xác thực hai yếu tố” khi đăng nhập tài khoản là gì?", "a": "Ngoài mật khẩu, phải xác minh thêm bằng yếu tố khác như mã OTP, vân tay, khuôn mặt", "w": ["Nhập mật khẩu hai lần liên tiếp để chắc chắn không gõ sai", "Trả lời thêm câu hỏi bảo mật do chính mình đặt sẵn", "Đặt mật khẩu có cả chữ cái và chữ số"], "h": "Yếu tố thứ hai phải khác loại với mật khẩu.", "e": "Hai yếu tố phải khác loại: thứ bạn biết (mật khẩu) và thứ bạn có hoặc chính bạn (điện thoại nhận OTP, vân tay, khuôn mặt). Nhập lại mật khẩu hay trả lời câu hỏi bảo mật vẫn chỉ là “thứ bạn biết”, kẻ gian đã biết mật khẩu thì cũng có thể biết những thứ này. Mật khẩu có chữ và số chỉ là mật khẩu mạnh hơn."}, {"q": "Có người gọi điện xưng là công an, nói bạn liên quan vụ án và yêu cầu chuyển tiền vào “tài khoản tạm giữ” để điều tra. Trường hợp nào thì làm theo?", "a": "Không trường hợp nào, đây là thủ đoạn lừa đảo", "w": ["Khi người gọi đọc chính xác họ tên, số căn cước của bạn", "Khi họ gửi kèm ảnh giấy triệu tập có đóng dấu đỏ qua Zalo", "Khi họ cam kết hoàn trả lại tiền ngay trong ngày"], "h": "Công an làm việc bằng giấy mời trực tiếp, không yêu cầu chuyển tiền qua điện thoại.", "e": "Cơ quan công an không làm việc qua điện thoại để yêu cầu chuyển tiền; không có “tài khoản tạm giữ” nào như vậy. Kẻ gian thường biết trước thông tin cá nhân, làm giả giấy triệu tập và hứa hoàn tiền để tạo lòng tin. Khi nghi ngờ, hãy đến trực tiếp Công an phường."}, {"q": "Nguồn nào sau đây an toàn để cài ứng dụng cho điện thoại?", "a": "Kho ứng dụng chính thức như CH Play (Google Play) hoặc App Store", "w": ["Đường link “cán bộ” gửi qua Zalo để cài bản dịch vụ công mới", "File cài đặt tải từ trang web có giao diện giống trang cơ quan nhà nước", "Đường link trong tin nhắn hiện đúng tên ngân hàng của bạn"], "h": "Hãy cài từ “cửa hàng” chính hãng có sẵn trên máy.", "e": "Kẻ gian thường gửi link hoặc file cài ứng dụng giả mạo (kể cả giả ứng dụng dịch vụ công, giả trang nhà nước, giả tin nhắn ngân hàng) để chiếm quyền điều khiển điện thoại và rút tiền. Kho ứng dụng chính thức có kiểm duyệt nên an toàn hơn."}, {"q": "Chữ “https” và biểu tượng ổ khóa ở đầu địa chỉ trang web cho biết điều gì?", "a": "Kết nối giữa máy bạn và trang web được mã hóa, nhưng chưa chứng minh trang đó là thật", "w": ["Trang web đã được cơ quan nhà nước kiểm duyệt, an toàn tuyệt đối", "Trang web không thể bị kẻ gian làm giả", "Trang web không chứa virus hay mã độc"], "h": "Ổ khóa bảo vệ “đường truyền”, không bảo đảm “người bán”.", "e": "“https” chỉ cho biết dữ liệu truyền đi được mã hóa. Trang lừa đảo, trang chứa mã độc vẫn có thể có https, và không có cơ quan nào kiểm duyệt mọi trang có ổ khóa. Vẫn phải kiểm tra kỹ địa chỉ trang web."}, {"q": "Mã VietQR giúp người dân làm gì?", "a": "Quét một mã để chuyển tiền đến tài khoản ở nhiều ngân hàng khác nhau", "w": ["Chỉ chuyển được tiền giữa các tài khoản trong cùng một ngân hàng", "Chỉ dùng cho ví điện tử, không dùng cho tài khoản ngân hàng", "Chỉ dùng để thanh toán tại siêu thị có máy quẹt thẻ"], "h": "“Viet” là Việt Nam, “QR” là loại mã vuông bạn hay quét.", "e": "VietQR là nhận diện chung cho dịch vụ thanh toán, chuyển khoản bằng mã QR qua mạng lưới NAPAS và các ngân hàng thành viên, ra mắt tháng 6/2021, giúp quét một mã để chuyển khoản liên ngân hàng nhanh chóng."}, {"q": "Cách nào giúp không mất ảnh, danh bạ, tài liệu khi điện thoại bị hỏng hoặc mất?", "a": "Sao lưu định kỳ lên dịch vụ lưu trữ đám mây hoặc sang thiết bị khác", "w": ["Chuyển toàn bộ dữ liệu vào thẻ nhớ gắn trong chính điện thoại đó", "Cài ứng dụng diệt virus và dọn rác thường xuyên", "Đặt mật khẩu khóa màn hình thật mạnh"], "h": "Hãy cất một “bản sao” ở nơi khác, không nằm trong máy.", "e": "Sao lưu ra nơi khác giúp khôi phục dữ liệu khi máy hỏng hay mất. Thẻ nhớ gắn trong máy sẽ mất theo máy; diệt virus và mật khẩu màn hình giúp bảo mật nhưng không tạo bản sao dữ liệu."}, {"q": "Khi buộc phải gửi ảnh chụp thẻ căn cước cho một đơn vị đáng tin, cách nào an toàn hơn?", "a": "Ghi chú mục đích lên ảnh, ví dụ “Chỉ dùng để nộp hồ sơ … – ngày …”", "w": ["Gửi qua Zalo là đủ an toàn vì tin nhắn đã được mã hóa", "Gửi kèm ảnh chân dung cầm thẻ để đơn vị dễ xác minh", "Che số thẻ, giữ nguyên các thông tin còn lại"], "h": "Hãy “đánh dấu” để tấm ảnh không bị dùng vào việc khác.", "e": "Ghi chú mục đích lên ảnh giúp hạn chế kẻ gian dùng lại để mở tài khoản, vay tiền giả mạo. Mã hóa đường truyền không ngăn người nhận dùng sai ảnh; ảnh cầm thẻ là thứ kẻ gian rất cần; che số thẻ thì ảnh thường không còn dùng được cho mục đích chính đáng."}, {"q": "Phong trào “Bình dân học vụ số” nhằm mục đích chính nào?", "a": "Phổ cập kiến thức, kỹ năng số cơ bản cho mọi người dân", "w": ["Xóa mù chữ cho người lớn tuổi chưa biết đọc, viết", "Đào tạo chuyên sâu về lập trình, AI cho học sinh, sinh viên", "Hỗ trợ mỗi hộ gia đình một thiết bị thông minh"], "h": "Tên gọi kế thừa phong trào “Bình dân học vụ” năm 1945, thêm chữ “số”.", "e": "Phong trào được triển khai theo Kế hoạch số 01-KH/BCĐTW ngày 21/3/2025 của Ban Chỉ đạo Trung ương về phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, có nền tảng học tập binhdanhocvuso.gov.vn. Xóa mù chữ là mục tiêu của phong trào Bình dân học vụ năm 1945; đào tạo chuyên sâu hay phát thiết bị không phải mục tiêu chính."}, {"q": "Đang gọi video, người thân bất ngờ hỏi vay tiền gấp. Cách xác minh nào an toàn nhất?", "a": "Cúp máy, gọi lại vào số điện thoại quen thuộc của người đó hoặc hỏi trực tiếp người nhà", "w": ["Đề nghị họ bật camera lâu hơn để nhìn kỹ khuôn mặt", "Kiểm tra tên hiển thị trên Zalo, Facebook đúng là của người thân", "Chuyển trước một ít tiền để thử xem họ có thật không"], "h": "Đừng chỉ tin vào màn hình và tài khoản đang gọi cho bạn.", "e": "Kẻ gian có thể chiếm tài khoản mạng xã hội của người thân và dùng AI giả khuôn mặt, giọng nói, nên nhìn lâu hay xem tên tài khoản đều không đủ. Chuyển thử tiền là đã mất tiền. Gọi lại qua số quen hoặc hỏi người nhà là cách chắc chắn nhất."}], "kho": [{"q": "Ba trụ cột của chuyển đổi số quốc gia là gì?", "a": "Chính phủ số, kinh tế số, xã hội số", "w": ["Hạ tầng số, dữ liệu số, nhân lực số", "Chính phủ số, kinh tế số, đô thị thông minh", "Thể chế số, hạ tầng số, công dân số"], "h": "Ba trụ cột tương ứng với Nhà nước, doanh nghiệp và người dân.", "e": "Chương trình Chuyển đổi số quốc gia (Quyết định số 749/QĐ-TTg ngày 03/6/2020) xác định ba trụ cột: Chính phủ số, kinh tế số, xã hội số; Luật Chuyển đổi số 2025 cũng có các chương riêng về Chính phủ số và kinh tế số, xã hội số. Hạ tầng số, dữ liệu số, nhân lực số, thể chế là các yếu tố nền tảng, bảo đảm; đô thị thông minh là một mô hình ứng dụng."}, {"q": "Văn bản nào quy định ngày 10/10 hằng năm là Ngày Chuyển đổi số quốc gia?", "a": "Quyết định số 505/QĐ-TTg năm 2022 của Thủ tướng Chính phủ", "w": ["Quyết định số 749/QĐ-TTg năm 2020 của Thủ tướng Chính phủ", "Quyết định số 06/QĐ-TTg năm 2022 của Thủ tướng Chính phủ", "Nghị quyết số 57-NQ/TW năm 2024 của Bộ Chính trị"], "h": "Số hiệu văn bản có 3 chữ số, đọc xuôi hay đọc ngược đều giống nhau.", "e": "Quyết định số 505/QĐ-TTg ngày 22/4/2022 quy định Ngày Chuyển đổi số quốc gia. Quyết định 749 phê duyệt Chương trình Chuyển đổi số quốc gia; Quyết định 06 phê duyệt Đề án 06; Nghị quyết 57 về đột phá phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia."}, {"q": "Nghị quyết số 57-NQ/TW ngày 22/12/2024 của Bộ Chính trị về vấn đề gì?", "a": "Đột phá phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia", "w": ["Phát triển kinh tế tư nhân", "Hội nhập quốc tế trong tình hình mới", "Đổi mới công tác xây dựng và thi hành pháp luật"], "h": "Nghị quyết này là căn cứ quan trọng của ngày hội hôm nay.", "e": "Nghị quyết 57-NQ/TW xác định khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số là đột phá quan trọng hàng đầu để phát triển đất nước. Ba nội dung còn lại thuộc các nghị quyết khác của Bộ Chính trị."}, {"q": "Luật Chuyển đổi số được Quốc hội thông qua ngày 11/12/2025 có hiệu lực từ ngày nào?", "a": "01/7/2026", "w": ["01/01/2026", "11/12/2025", "10/10/2026"], "h": "Luật đã có hiệu lực trước Ngày Chuyển đổi số năm nay.", "e": "Luật Chuyển đổi số số 148/2025/QH15 gồm 8 chương, 48 điều, được thông qua ngày 11/12/2025 và có hiệu lực từ 01/7/2026, thay thế Luật Công nghệ thông tin năm 2006. Ngày thông qua và ngày có hiệu lực của một luật thường khác nhau."}, {"q": "Theo Luật Giao dịch điện tử 2023, chữ ký số có giá trị pháp lý như thế nào?", "a": "Tương đương chữ ký của người đó trên văn bản giấy", "w": ["Chỉ có giá trị khi in ra và đóng dấu xác nhận", "Chỉ có giá trị trong giao dịch giữa các cơ quan nhà nước", "Chỉ có giá trị như bản sao, khi cần phải kèm bản ký tay"], "h": "Chữ ký số giúp ký hồ sơ mà không cần in giấy.", "e": "Điều 23 Luật Giao dịch điện tử 2023 (số 20/2023/QH15, hiệu lực từ 01/7/2024) quy định chữ ký số có giá trị pháp lý tương đương chữ ký của cá nhân đó trong văn bản giấy. Chữ ký số dùng được cho cả cá nhân, doanh nghiệp, không cần in ra hay kèm bản ký tay."}, {"q": "Kẻ gian dùng AI tạo hình ảnh, giọng nói giống hệt người thân để gọi video lừa tiền. Hình thức giả mạo đó gọi là gì?", "a": "Deepfake", "w": ["Phishing", "Spoofing", "Malware"], "h": "Tên gồm hai từ tiếng Anh có nghĩa là “sâu” và “giả”.", "e": "Deepfake là dùng AI ghép, giả mạo khuôn mặt, giọng nói. Phishing là lừa đảo bằng trang web, email, tin nhắn giả để lấy thông tin; spoofing là giả mạo số điện thoại hoặc địa chỉ người gửi; malware là phần mềm độc hại."}, {"q": "Trong các vụ việc ở Việt Nam thời gian qua, kẻ gian dùng trạm phát sóng giả (BTS giả) chủ yếu để làm gì?", "a": "Phát tán tin nhắn giả mạo tên ngân hàng, nhà mạng kèm đường link lừa đảo", "w": ["Rút tiền trực tiếp từ tài khoản ngân hàng qua sóng điện thoại", "Lấy trộm ảnh, danh bạ trong điện thoại ở gần trạm", "Chặn sóng để người dân không nhận được mã OTP"], "h": "Tin nhắn hiện đúng tên thương hiệu quen thuộc chưa chắc đã thật.", "e": "Trạm BTS giả ép điện thoại ở gần kết nối rồi gửi tin nhắn mang tên ngân hàng, nhà mạng giả. Bản thân trạm không rút được tiền hay lấy dữ liệu trong máy; tiền chỉ mất khi người dùng bấm link và nhập thông tin. Không bấm link trong tin nhắn, kể cả khi hiện tên ngân hàng."}, {"q": "“Điện toán đám mây” là gì?", "a": "Lưu trữ, xử lý dữ liệu trên hệ thống máy chủ qua Internet thay vì chỉ trên máy cá nhân", "w": ["Mạng Internet phát xuống từ vệ tinh quỹ đạo tầm thấp", "Kho dữ liệu đặt trên máy tính cá nhân, chia sẻ qua mạng nội bộ", "Công nghệ dự báo thời tiết bằng siêu máy tính"], "h": "“Đám mây” ở đây không nằm trên bầu trời.", "e": "Điện toán đám mây cho phép lưu trữ, sử dụng dữ liệu và phần mềm qua Internet, truy cập ở mọi nơi; ví dụ Google Drive, iCloud. Internet vệ tinh là hạ tầng kết nối; kho dữ liệu trên máy cá nhân là lưu trữ cục bộ; dự báo thời tiết là một ứng dụng khác."}, {"q": "“Internet vạn vật” (IoT) là gì?", "a": "Các thiết bị như camera, đồng hồ, máy lạnh… kết nối Internet để trao đổi dữ liệu, điều khiển từ xa", "w": ["Mạng Internet tốc độ cao dùng công nghệ 5G", "Mạng xã hội kết nối mọi người trên thế giới", "Hệ thống lưu trữ dữ liệu trên Internet"], "h": "“Vạn vật” nghĩa là mọi đồ vật.", "e": "IoT là mạng lưới thiết bị gắn cảm biến, kết nối Internet để thu thập, trao đổi dữ liệu, ví dụ camera giám sát, đèn đường thông minh. 5G là công nghệ mạng di động; mạng xã hội kết nối con người; lưu trữ trên Internet là điện toán đám mây."}, {"q": "Làm thủ tục hành chính, thông tin về cư trú đã có trong cơ sở dữ liệu thì người dân có phải nộp giấy tờ chứng minh nơi cư trú không?", "a": "Không, cơ quan giải quyết khai thác thông tin từ cơ sở dữ liệu", "w": ["Có, phải nộp giấy xác nhận thông tin về cư trú do công an cấp", "Có, phải nộp bản sao thẻ căn cước có chứng thực", "Chỉ không phải nộp nếu có tài khoản định danh mức độ 2"], "h": "Nguyên tắc là để dữ liệu “chạy” thay người dân.", "e": "Từ khi bỏ sổ hộ khẩu, Nghị định 104/2022/NĐ-CP quy định các cách khai thác thông tin cư trú thay cho việc xuất trình sổ. Theo định hướng của Đề án 06, cơ quan nhà nước khai thác dữ liệu sẵn có thay vì yêu cầu người dân nộp giấy tờ chứng minh; giấy xác nhận cư trú chỉ dùng khi chưa khai thác được dữ liệu."}, {"q": "Khi hỏi chatbot AI về thủ tục, quy định pháp luật, điều quan trọng nhất cần lưu ý là gì?", "a": "AI có thể trả lời sai hoặc dùng thông tin cũ, cần đối chiếu văn bản chính thức", "w": ["Câu trả lời của AI đã được cơ quan nhà nước kiểm duyệt nên dùng được ngay", "Hỏi vài chatbot khác nhau, nếu trả lời giống nhau thì chắc chắn đúng", "AI chỉ sai với câu hỏi khó, câu hỏi đơn giản thì luôn đúng"], "h": "Ngay cả người thông minh nhất cũng có lúc nhầm.", "e": "AI là công cụ hỗ trợ hữu ích nhưng có thể nhầm lẫn kể cả với câu hỏi đơn giản; nhiều chatbot có thể cùng sai vì học từ nguồn giống nhau. Câu trả lời của AI không được kiểm duyệt và không có giá trị pháp lý; hãy đối chiếu văn bản hoặc hỏi Trung tâm Phục vụ hành chính công phường."}, {"q": "Khi nhờ chatbot AI hỗ trợ, cách làm nào sau đây là AN TOÀN?", "a": "Thay thông tin cá nhân bằng thông tin giả định (ví dụ “ông A, số nhà X”) trước khi hỏi", "w": ["Gửi ảnh thẻ căn cước để AI điền giúp tờ khai cho nhanh", "Nhập mật khẩu ngân hàng để AI kiểm tra xem đã đủ mạnh chưa", "Dán nguyên tin nhắn chứa mã OTP để AI xem có phải lừa đảo không"], "h": "Hãy hỏi về “trường hợp”, đừng đưa “chìa khóa” của mình.", "e": "Không nên đưa giấy tờ tùy thân, mật khẩu, mã OTP vào chatbot hay trang web lạ, vì có thể bị lưu lại hoặc lộ ra ngoài. Thay thông tin thật bằng thông tin giả định vẫn giúp bạn được tư vấn mà không lộ dữ liệu cá nhân."}, {"q": "“Chính phủ số” hướng tới mục tiêu nào?", "a": "Hoạt động dựa trên dữ liệu và công nghệ số, phục vụ người dân tốt hơn, lấy người dân làm trung tâm", "w": ["Chuyển toàn bộ hồ sơ giấy thành file scan lưu trên máy tính", "Bắt buộc mọi người dân chỉ được làm thủ tục qua mạng", "Thay thế cán bộ tiếp dân bằng máy móc, robot"], "h": "Trung tâm của Chính phủ số vẫn là con người.", "e": "Chính phủ số dùng dữ liệu và công nghệ số để ra quyết định nhanh, minh bạch, cung cấp dịch vụ công thuận tiện. Scan hồ sơ chỉ là số hóa; người dân vẫn có thể làm thủ tục trực tiếp; công nghệ hỗ trợ chứ không thay thế con người."}, {"q": "Từ ngày 01/7/2025, chính quyền địa phương ở nước ta được tổ chức như thế nào?", "a": "Hai cấp: cấp tỉnh và cấp xã (xã, phường, đặc khu)", "w": ["Ba cấp: cấp tỉnh, cấp huyện và cấp xã", "Hai cấp: cấp tỉnh và cấp huyện", "Ba cấp: cấp tỉnh, cấp xã và khu phố, ấp"], "h": "Cấp huyện đã kết thúc hoạt động.", "e": "Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, từ 01/7/2025 chính quyền địa phương được tổ chức ở cấp tỉnh và cấp xã; cả nước hiện có 34 tỉnh, thành phố và 3.321 xã, phường, đặc khu. Khu phố, ấp không phải là một cấp chính quyền."}, {"q": "Theo Quyết định 2345/QĐ-NHNN (hiệu lực từ 01/7/2024), chuyển tiền trực tuyến trên 10 triệu đồng/lần phải xác thực bằng cách nào?", "a": "Xác thực sinh trắc học (khuôn mặt hoặc vân tay)", "w": ["Nhập mã Smart OTP gửi về ứng dụng", "Nhập lại mật khẩu đăng nhập thêm một lần", "Xác nhận qua cuộc gọi từ tổng đài ngân hàng"], "h": "Gương mặt của bạn chính là chìa khóa.", "e": "Quyết định 2345/QĐ-NHNN ngày 18/12/2023 quy định chuyển tiền trên 10 triệu đồng/lần hoặc tổng trên 20 triệu đồng/ngày phải xác thực sinh trắc học; các giao dịch nhỏ hơn mức đó vẫn dùng mã OTP. Biện pháp này giúp chống kẻ gian chiếm đoạt tài khoản."}]};
