/* ---------- sound (Web Audio, no files) ---------- */
const Snd={ctx:null,on:true,master:null,musicTimer:null,step:0,
  init(){ if(this.ctx) {if(this.ctx.state==="suspended") this.ctx.resume(); return}
    const C=window.AudioContext||window.webkitAudioContext; if(!C) return;
    this.ctx=new C(); this.master=this.ctx.createGain(); this.master.gain.value=this.on?1:0; this.master.connect(this.ctx.destination);
    const len=this.ctx.sampleRate*0.05, b=this.ctx.createBuffer(1,len,this.ctx.sampleRate), d=b.getChannelData(0);
    for(let i=0;i<len;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/len,2); this.clapBuf=b; },
  set(on){ this.on=on; if(this.master) this.master.gain.setTargetAtTime(on?1:0,this.ctx.currentTime,.05) },
  tone(f,dur,type="sine",vol=.18,at=0,slide){ if(!this.ctx) return; const t=this.ctx.currentTime+at, o=this.ctx.createOscillator(), g=this.ctx.createGain();
    o.type=type; o.frequency.setValueAtTime(f,t); if(slide) o.frequency.exponentialRampToValueAtTime(slide,t+dur);
    g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(vol,t+.015); g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t+dur+.05) },
  click(){ this.tone(660,.08,"triangle",.12) },
  pick(){ this.tone(330,.25,"sine",.12); this.tone(440,.25,"sine",.08,.18) },
  correct(){ [523,659,784,1047].forEach((f,i)=>this.tone(f,.32,"triangle",.16,i*.09)) },
  wrong(){ this.tone(392,.35,"sawtooth",.07); this.tone(330,.5,"sawtooth",.07,.22,262) },
  beep(hi){ this.tone(hi?1046:784,hi?.4:.18,"square",.07) },
  tick(){ this.tone(1200,.04,"square",.035) },
  applause(sec=1.5,rate=60){ if(!this.ctx) return; const t0=this.ctx.currentTime, n=Math.floor(sec*rate);
    for(let i=0;i<n;i++){ const at=Math.random()*sec, env=Math.min(1,at/.25)*Math.min(1,(sec-at)/.5);
      const s=this.ctx.createBufferSource(); s.buffer=this.clapBuf; s.playbackRate.value=.8+Math.random()*.6;
      const f=this.ctx.createBiquadFilter(); f.type="bandpass"; f.frequency.value=900+Math.random()*1800; f.Q.value=.9;
      const g=this.ctx.createGain(); g.gain.value=.25*env*(.5+Math.random()*.5);
      s.connect(f); f.connect(g); g.connect(this.master); s.start(t0+at) } },
  music(on){ clearInterval(this.musicTimer); if(!on||!this.ctx) return;
    const seq=[392,0,523,0,587,0,523,659,0,587,0,523,440,0,392,0];
    this.musicTimer=setInterval(()=>{ const f=seq[this.step++%seq.length]; if(f) this.tone(f,.5,"sine",.035); if(this.step%8===1) this.tone(196,1.1,"triangle",.03) },260) }
};
const ICON_ON='<svg viewBox="0 0 24 24" fill="none" stroke="#F3F7FF" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M16 9a4 4 0 0 1 0 6M19 6a8 8 0 0 1 0 12"/></svg>';
const ICON_OFF='<svg viewBox="0 0 24 24" fill="none" stroke="#F3F7FF" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M17 9l5 6M22 9l-5 6"/></svg>';
