/* ---------- screens & overlays ---------- */
function show(id){ document.querySelectorAll(".screen").forEach(s=>s.classList.toggle("on",s.id===id)) }
function openOv(id){ $(id).classList.add("on") } function closeOv(id){ $(id).classList.remove("on") }
