/* binary rain */
(function(){ const box=$("binary"); for(let i=0;i<14;i++){ const s=document.createElement("span");
  s.textContent=Array.from({length:14},()=>Math.random()<.5?"1":"0").join(""); s.style.left=(i*7.3+Math.random()*3)+"%";
  s.style.animationDuration=(14+Math.random()*16)+"s"; s.style.animationDelay=(-Math.random()*25)+"s"; box.appendChild(s) } })();

/* ---------- game state ---------- */
let G=null, timerRAF=null, deadline=0, remain=TIME, paused=false, lastSec=TIME;
let runStart=0; /* đếm tổng thời gian trả lời (ẩn, chỉ hiện ở màn kết quả) */
function newGame(){
  const pools={}; for(const k of ["de","tb","kho"]) pools[k]=shuffle(QB[k].map((q,i)=>({...q,id:k+i})));
  G={pools, used:new Set(), idx:0, score:0, lives:{fifty:true,swap:true,cns:true}, q:null, locked:false, ms:0};
}
function levelOf(i){ return i<5?"de":i<10?"tb":"kho" }
function drawQuestion(){ const lv=levelOf(G.idx); const q=G.pools[lv].find(x=>!G.used.has(x.id)); G.used.add(q.id); return q }

function renderQ(){
  const q=G.q, lv=levelOf(G.idx);
  $("qNum").textContent=`Câu ${G.idx+1}/15`;
  $("scoreChip").innerHTML=`<svg viewBox="0 0 24 24" fill="#FFC83D"><path d="M12 2l3 6.5 7 .8-5.2 4.8 1.4 7L12 17.6 5.8 21l1.4-7L2 9.3l7-.8z"/></svg>${G.score} điểm`;
  $("qLevel").textContent=`Câu này ${SCORES[G.idx]} điểm`;
  $("qText").textContent=q.q;
  const opts=shuffle([{t:q.a,ok:true},...q.w.map(t=>({t,ok:false}))]);
  const box=$("answers"); box.innerHTML="";
  opts.forEach((o,i)=>{ const b=document.createElement("button"); b.className="ans"; b.dataset.ok=o.ok?"1":"";
    b.innerHTML=`<span class="key">${"ABCD"[i]}</span><span></span>`; b.lastChild.textContent=o.t;
    b.onclick=()=>choose(b); box.appendChild(b) });
  $("l5050").disabled=!G.lives.fifty; $("lSwap").disabled=!G.lives.swap; $("lCns").disabled=!G.lives.cns;
  G.locked=false;
}

/* timer */
const CIRC=2*Math.PI*28; $("ring").style.strokeDasharray=CIRC;
function startTimer(sec=TIME){ stopTimer(); remain=sec; deadline=performance.now()+sec*1000; paused=false; lastSec=Math.ceil(sec); runStart=performance.now(); loop() }
function loop(){ const left=Math.max(0,(deadline-performance.now())/1000); remain=left; paintTimer(left);
  const s=Math.ceil(left); if(s!==lastSec){ lastSec=s; if(s<=10&&s>0) Snd.tick() }
  if(left<=0){ timeUp(); return } timerRAF=requestAnimationFrame(loop) }
function paintTimer(left){ $("tNum").textContent=Math.ceil(left); $("ring").style.strokeDashoffset=CIRC*(1-left/TIME); $("timer").classList.toggle("low",left<=10) }
function stopTimer(){ cancelAnimationFrame(timerRAF); timerRAF=null;
  if(runStart && G){ G.ms+=Math.min(performance.now(),deadline)-runStart } runStart=0 }
function pauseTimer(){ if(timerRAF){ stopTimer(); paused=true } }
function resumeTimer(){ if(paused && !G.locked){ startTimer(remain) } }
document.addEventListener("visibilitychange",()=>{ if(document.hidden) pauseTimer(); else if($("game").classList.contains("on") && !$("hintOv").classList.contains("on")) resumeTimer() });

/* lifelines */
$("l5050").onclick=()=>{ if(G.locked||!G.lives.fifty) return; Snd.click(); G.lives.fifty=false; $("l5050").disabled=true;
  const wrong=shuffle([...document.querySelectorAll(".ans")].filter(b=>!b.dataset.ok)).slice(0,2);
  wrong.forEach(b=>{ b.classList.add("gone"); b.disabled=true }) };
$("lSwap").onclick=()=>{ if(G.locked||!G.lives.swap) return; Snd.click(); G.lives.swap=false; G.q=drawQuestion(); renderQ(); startTimer(TIME) };
$("lCns").onclick=()=>{ if(G.locked||!G.lives.cns) return; Snd.click(); G.lives.cns=false; $("lCns").disabled=true; pauseTimer();
  $("hintText").textContent=G.q.h; openOv("hintOv") };
$("hintClose").onclick=()=>{ Snd.click(); closeOv("hintOv"); resumeTimer() };
$("volWrap").innerHTML=volunteerSVG();

/* answering */
async function choose(btn){ if(G.locked) return; G.locked=true; stopTimer(); Snd.pick();
  document.querySelectorAll(".ans").forEach(b=>b.disabled=true); btn.classList.add("pick");
  await wait(reduce?300:1500); reveal(btn) }
function timeUp(){ if(G.locked) return; G.locked=true; stopTimer(); document.querySelectorAll(".ans").forEach(b=>b.disabled=true); reveal(null) }
function reveal(btn){
  const right=[...document.querySelectorAll(".ans")].find(b=>b.dataset.ok);
  const ok=!!(btn && btn.dataset.ok);
  if(btn) btn.classList.remove("pick");
  right.classList.add("right"); if(btn && !ok) btn.classList.add("wrong");
  const cit=document.querySelector("#gameStage .citizen"), host=document.querySelector("#gameStage .host");
  if(ok){ G.score=SCORES[G.idx]; Snd.correct(); Snd.applause(1.4,55); sparks(right);
    cit.classList.remove("cheer"); void cit.offsetWidth; cit.classList.add("cheer"); host.classList.remove("nod"); void host.offsetWidth; host.classList.add("nod") }
  else Snd.wrong();
  const v=$("verdict");
  v.className="verdict "+(ok?"ok":"no");
  v.innerHTML=(ok?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12l5 5L20 6"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>')
    +(ok?"Chính xác!":btn?"Chưa đúng rồi":"Hết giờ!");
  $("correctLine").innerHTML=ok?`Bạn đang có <b>${G.score} điểm</b>.`:`Đáp án đúng: <b></b>`;
  if(!ok) $("correctLine").querySelector("b").textContent=G.q.a;
  $("explain").textContent=G.q.e;
  $("nextBtn").textContent=(ok && G.idx<14)?"Câu tiếp theo":"Xem kết quả";
  $("nextBtn").dataset.mode=(ok && G.idx<14)?"next":"end";
  setTimeout(()=>{ $("sheet").classList.add("on"); $("nextBtn").focus({preventScroll:true}) }, ok?700:500);
}
$("nextBtn").onclick=async ()=>{ Snd.click(); $("sheet").classList.remove("on");
  if($("nextBtn").dataset.mode==="next"){ await climb(G.idx+1); G.idx++; G.q=drawQuestion(); renderQ(); startTimer(TIME) }
  else finish() };

/* ladder */
function buildLadder(now, done){ const ol=$("ladder"); ol.innerHTML="";
  for(let i=14;i>=0;i--){ const li=document.createElement("li"); const lv=levelOf(i);
    li.innerHTML=`<span>Câu ${i+1}</span><span>${SCORES[i]}</span>`;
    if(i<done) li.classList.add("done"); if(i===now) li.classList.add("now"); if(i===14) li.classList.add("top"); ol.appendChild(li) } }
async function climb(nextIdx){ buildLadder(nextIdx-1, nextIdx-1); $("ladderClose").hidden=true; openOv("ladderOv");
  await wait(reduce?300:700); buildLadder(nextIdx, nextIdx); Snd.tone(880,.15,"triangle",.1);
  await wait(reduce?300:1300); closeOv("ladderOv"); $("ladderClose").hidden=false; await wait(200) }
$("scoreChip").onclick=()=>{ Snd.click(); buildLadder(G.idx, G.idx); openOv("ladderOv") };

/* sparks & fireworks */
function sparks(el){ if(reduce) return; const r=el.getBoundingClientRect();
  for(let i=0;i<22;i++){ const s=document.createElement("i"); s.className="spark";
    s.style.left=(r.left+r.width*Math.random())+"px"; s.style.top=(r.top+r.height/2)+"px";
    s.style.background=Math.random()<.5?"#FFC83D":"#3FD6E8";
    s.style.setProperty("--dx",(Math.random()*120-60)+"px"); s.style.setProperty("--dy",(-40-Math.random()*90)+"px");
    document.body.appendChild(s); setTimeout(()=>s.remove(),900) } }
let fxRun=false;
function fireworks(sec=6){ const c=$("fx"), x=c.getContext("2d"); c.width=innerWidth; c.height=innerHeight; const P=[]; fxRun=true; const end=performance.now()+sec*1000;
  const cols=["#FFC83D","#3FD6E8","#E5484D","#7CF0B3","#ffffff"];
  function burst(){ const cx=c.width*(.15+Math.random()*.7), cy=c.height*(.12+Math.random()*.35), col=cols[Math.floor(Math.random()*cols.length)];
    for(let i=0;i<46;i++){ const a=Math.PI*2*i/46, v=2+Math.random()*3.2; P.push({x:cx,y:cy,vx:Math.cos(a)*v,vy:Math.sin(a)*v,l:1,c:col}) } Snd.tone(180+Math.random()*80,.25,"triangle",.05) }
  let last=0;(function f(t){ if(!fxRun) { x.clearRect(0,0,c.width,c.height); return }
    if(t<end && t-last>520){ burst(); last=t }
    x.clearRect(0,0,c.width,c.height);
    for(let i=P.length-1;i>=0;i--){ const p=P[i]; p.x+=p.vx; p.y+=p.vy; p.vy+=.05; p.vx*=.985; p.l-=.012; if(p.l<=0){P.splice(i,1);continue}
      x.globalAlpha=p.l; x.fillStyle=p.c; x.fillRect(Math.round(p.x/4)*4,Math.round(p.y/4)*4,4,4) }
    if(t<end||P.length) requestAnimationFrame(f); else fxRun=false })(performance.now()) }

/* ---------- flow ---------- */
async function playIntro(){
  show("intro"); $("introStage").innerHTML=stageHTML("Ngày Chuyển đổi số quốc gia");
  const actor=document.querySelector("#introStage .a-citizen .who"), cit=actor.querySelector(".citizen"), host=document.querySelector("#introStage .host");
  actor.classList.add("walker"); $("introCap").textContent="Xin mời người chơi lên sân khấu!";
  await wait(350); Snd.applause(3.2,70); actor.classList.add("walk"); await wait(reduce?200:1550);
  cit.classList.add("waving"); host.classList.add("nod"); $("introCap").textContent="Chào mọi người!";
  await wait(reduce?300:1500); cit.classList.remove("waving"); cit.classList.add("sitting"); $("introCap").textContent="Chúng ta cùng bắt đầu nhé!";
  await wait(600);
  for(const n of ["3","2","1"]){ $("countdown").innerHTML=`<span>${n}</span>`; Snd.beep(false); await wait(800) }
  $("countdown").innerHTML=""; Snd.beep(true);
}
async function startGame(){ Snd.init(); Snd.click(); Snd.music(false); newGame(); await playIntro();
  $("gameStage").innerHTML=stageHTML("Ngày Chuyển đổi số quốc gia"); document.querySelector("#gameStage .citizen").classList.add("sitting");
  G.q=drawQuestion(); renderQ(); $("sheet").classList.remove("on"); show("game"); Snd.music(true); startTimer(TIME) }
function finish(){ stopTimer(); Snd.music(false); const correct=G.idx+(G.score===SCORES[G.idx]?1:0);
  $("endStage").innerHTML=stageHTML("Ngày Chuyển đổi số quốc gia");
  const cit=document.querySelector("#endStage .citizen"), host=document.querySelector("#endStage .host");
  let title, msg;
  if(correct>=15){ title="Xin chúc mừng Công dân số thông thái!"; msg="Bạn đã trả lời đúng cả 15 câu. Hãy chia sẻ những điều vừa học với người thân để cả nhà cùng an toàn trên không gian mạng.";
    cit.classList.add("waving"); host.classList.add("nod"); Snd.applause(5,90); setTimeout(()=>Snd.correct(),300); fireworks(6) }
  else if(correct>=5){ title=`Chúc mừng bạn đạt ${G.score} điểm!`; msg=["Đừng quên: không ai được phép hỏi mã OTP của bạn, kể cả người xưng là ngân hàng hay công an.","Cài VNeID mức độ 2 và dùng dịch vụ công trực tuyến để đỡ phải đi lại.","Gặp đường link lạ, hãy dừng lại và hỏi Tổ công nghệ số cộng đồng ở khu phố."][Math.floor(Math.random()*3)];
    cit.classList.add("sitting","cheer"); Snd.applause(2.4,70) }
  else { title="Chúc bạn may mắn lần sau!"; msg="Mỗi ngày học thêm một kỹ năng số, bạn sẽ là công dân số thông thái."; cit.classList.add("sitting") }
  $("endTitle").textContent=title; $("endScore").innerHTML=`${G.score}<small>điểm</small>`; $("endMsg").textContent=msg;
  show("end"); LB.onFinish({score:G.score, correct, ms:G.ms}) }
$("startBtn").onclick=()=>{ Snd.init(); Snd.click(); LB.openReg() };
LB.bindReg(startGame);
$("lbBtn").onclick=()=>{ Snd.init(); Snd.click(); LB.openBoard() };
$("endLbBtn").onclick=()=>{ Snd.click(); LB.openBoard() };
$("againBtn").onclick=()=>{ fxRun=false; if(LB.hasPlayer()) startGame(); else LB.openReg() };
$("homeBtn").onclick=()=>{ fxRun=false; Snd.click(); show("start") };
